# v1: v0 plus a deliberate draft chain, Treasure-emblem shards for gold, retreat when hurt
# inside monster danger, tribute at altars away from monoliths when possible, and focus on
# the weakest visible enemy when fighting.

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick(random_champion(pool))
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains(spawn_region(ally()), position())
if at_spawn:
    # Treasure emblem shards first for more gold, the rest as health shards
    let shards_bought = floor(gold() / 30)
    let treasure_shards = floor(shards_bought / 2)
    buy(shard_of(family_treasure(), stat_strength()), treasure_shards)
    buy(shard(stat_health()), shards_bought - treasure_shards)
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# recall at 20% health, or at 50% when carrying gems
if not at_spawn and (health() < 0.2 * max_health() or (gems() > 0 and health() < 0.5 * max_health())):
    recall()
    end_turn()

# hurt and in danger from awake camps or enemy champions: fall back toward spawn
if not at_spawn and in_danger() and health() < 0.6 * max_health():
    move_towards(closest(spawn_region(ally())))
    end_turn()

# fight: focus the weakest visible enemy in range
let enemy = first(filter(enemies_visible(), in_attack_range()))
if exists(enemy):
    if ability_ready(0):
        cast_at_unit(0, enemy)
    if ability_ready(1):
        cast_at_unit(1, enemy)
    attack(enemy)
    end_turn()

if gems() > 0:
    let open_altars = minus(altars(), locked_altars())
    # prefer altars away from monoliths, which kill gem carriers
    let safe_altars = minus(open_altars, ring(monolith_tiles(), 5))
    let use_altars = safe_altars
    if count(safe_altars) == 0:
        use_altars = open_altars
    let altar = first(filter(use_altars, within(1, position())))
    if exists(altar):
        tribute(altar)
        end_turn()
    move_towards(closest(ring(use_altars, 1)))
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first(filter(camps, in_attack_range()))
if exists(camp):
    if ability_ready(0):
        cast_at_unit(0, camp)
    if ability_ready(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus(camp_spawns, respawning_visible_spawns())

# standing on a cleared camp spawn: hold so the capture timer keeps running
if contains(goals, position()):
    end_turn()

move_towards(closest(goals))
let camp2 = first(filter(camps, in_attack_range()))
if exists(camp2):
    attack(camp2)
set_priority(1 + random_int(100))
end_turn()

